import { createCompositionPreview } from "../../../packages/renderer-core/src/index.ts";
import { WebglDevice } from "../../../packages/renderer-core/src/composition/render/webgl-device.ts";
import { WebglPaint } from "../../../packages/renderer-core/src/composition/render/webgl-paint.ts";
import { WebglVectors } from "../../../packages/renderer-core/src/composition/render/webgl-vectors.ts";
import { WebglReadback } from "../../../packages/renderer-core/src/composition/render/webgl-readback.ts";
const composition = {
  schemaVersion: "composition-1",
  id: "exposure-cost",
  width: 1920,
  height: 1080,
  fps: 30,
  frameCount: 60,
  background: "#26313b",
  assets: [],
  motionBlur: {
    enabled: false,
    shutterAngle: 360,
    shutterPhase: 0,
    samples: 2,
  },
  layers: [
    {
      id: "moving",
      type: "solid",
      size: [400, 300],
      color: "#d87047",
      motionBlur: true,
      transform: {
        anchor: [0, 0],
        position: {
          x: {
            keys: [
              { frame: 0, value: 100 },
              { frame: 59, value: 1400, interpolation: "linear" },
            ],
          },
          y: 300,
        },
        opacity: 0.6,
      },
    },
  ],
};
export function measure({ preflightOnly }) {
  const previews = {},
    canvases = {},
    restores = [];
  let enabled = false,
    stats = {};
  const hook = (target, name) => {
    const original = target[name];
    target[name] = function (...args) {
      if (!enabled) return Reflect.apply(original, this, args);
      const at = performance.now();
      try {
        return Reflect.apply(original, this, args);
      } finally {
        const key = target.constructor.name + "." + name;
        const value = (stats[key] ??= { calls: 0, ms: 0 });
        value.calls++;
        value.ms += performance.now() - at;
      }
    };
    restores.push(() => (target[name] = original));
  };
  const traversal = (backend, instrumented, barrier) => {
    const p = previews[backend],
      gl = canvases.webgl2.getContext("webgl2");
    enabled = false;
    p.renderFrame(20);
    p.readPixels();
    stats = {};
    const frames = [];
    for (let frame = 21; frame < 29; frame++) {
      enabled = instrumented && frame >= 24;
      const at = performance.now();
      p.renderFrame(frame);
      const submitted = performance.now();
      if (barrier) {
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array(4));
      }
      const completed = performance.now();
      const pixels = p.readPixels();
      const end = performance.now();
      if (pixels.length !== 8294400) throw Error("Owned byte length");
      if (frame >= 24)
        frames.push({
          frame,
          renderMs: submitted - at,
          barrierMs: completed - submitted,
          readMs: end - completed,
          totalMs: end - at,
        });
    }
    enabled = false;
    return {
      backend,
      instrumented,
      barrier,
      frames,
      stats: structuredClone(stats),
    };
  };
  try {
    for (const backend of ["canvas2d", "webgl2"]) {
      canvases[backend] = document.createElement("canvas");
      previews[backend] = createCompositionPreview(
        canvases[backend],
        composition,
        { images: new Map(), fonts: new Map() },
        { backend },
      );
    }
    if (preflightOnly) {
      for (const frame of [20, 24, 28]) {
        previews.canvas2d.renderFrame(frame);
        previews.webgl2.renderFrame(frame);
        const a = previews.canvas2d.readPixels(),
          b = previews.webgl2.readPixels();
        if (a.some((v, i) => v !== b[i])) throw Error("Native bytes differ");
      }
      return {
        composition,
        rendererVersion: previews.webgl2.rendererVersion,
        elapsedTimingsCaptured: false,
      };
    }
    for (const name of ["uploadRegion", "copyRegion", "pass", "readRegion"])
      hook(WebglDevice.prototype, name);
    hook(WebglPaint.prototype, "draw");
    hook(WebglVectors.prototype, "paint");
    hook(WebglVectors.prototype, "drawBatch");
    hook(WebglReadback.prototype, "read");
    hook(Uint8ClampedArray.prototype, "slice");
    const runs = [];
    for (let cycle = 0; cycle < 6; cycle++) {
      const items = [
        ["canvas2d", false, false],
        ["webgl2", false, false],
        ["webgl2", true, false],
        ["webgl2", true, true],
      ];
      if (cycle % 2) items.reverse();
      for (const [backend, instrumented, barrier] of items)
        runs.push({ cycle, ...traversal(backend, instrumented, barrier) });
    }
    enabled = false;
    previews.webgl2.renderFrame(24);
    previews.webgl2.readPixels();
    const cachedOwnedReadsMs = [];
    let previous;
    for (let i = 0; i < 60; i++) {
      const at = performance.now();
      const owned = previews.webgl2.readPixels();
      cachedOwnedReadsMs.push(performance.now() - at);
      if (owned === previous) throw Error("Readback ownership");
      previous = owned;
    }
    const reference = new Uint8ClampedArray(8294400);
    reference.fill(113);
    const standaloneOwnedCopiesMs = [];
    for (let i = 0; i < 60; i++) {
      const at = performance.now();
      const owned = reference.slice();
      standaloneOwnedCopiesMs.push(performance.now() - at);
      if (owned[4096] !== 113) throw Error("Copy control");
    }
    return {
      composition,
      rendererVersion: previews.webgl2.rendererVersion,
      runs,
      cachedOwnedReadsMs,
      standaloneOwnedCopiesMs,
      elapsedTimingsCaptured: true,
      acceptance: false,
      method:
        "Diagnostic attribution only. Each traversal uses preserved CE7 native count-one fixture and frames: frame20 setup/warmup (untimed),21-23 warm,24-28 measured; six alternating traversal orders. Nested hook times are inclusive and cannot be added. 1x1 forced read is an attribution barrier with its own cost. Uninstrumented matched runs expose hook overhead. Cached/standalone owned-copy controls include allocation/GC effects and are observed controls, not universal lower bounds.",
    };
  } finally {
    enabled = false;
    for (const restore of restores.reverse()) restore();
    try {
      previews.webgl2?.dispose();
    } finally {
      previews.canvas2d?.dispose();
    }
  }
}

