import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFile, writeFile, mkdtemp, rm } from "node:fs/promises";
import { resolve, join } from "node:path";
import { tmpdir } from "node:os";
import { createServer } from "vite";
import {
  launchRenderBrowser,
  probeRenderEnvironment,
  assertPinnedRenderEnvironment,
} from "@still-shift/execution-runtime";
const root = resolve(import.meta.dirname, "../../..");
const option = (key: string, fallback: string) => {
  const i = process.argv.indexOf(key);
  return i < 0 ? fallback : process.argv[i + 1]!;
};
const profile = process.argv.includes("--hardware") ? "hardware" : "pinned";
const sourceRef = option("--ref", "");
const preflightOnly = process.argv.includes("--preflight-only");
const output = resolve(
  option(
    "--output",
    `benchmarks/results/composition-ce6p/family-cost-${Date.now()}.json`,
  ),
);
const digest = (s: string | Buffer) =>
  createHash("sha256").update(s).digest("hex");
const workloads = () =>
  execFileSync("ps", ["-axo", "pid,command"], { encoding: "utf8" })
    .split("\n")
    .filter((line) => {
      const m = /^\s*(\d+)\s+(\S+)\s+(.*)$/.exec(line);
      if (!m || +m[1] === process.pid) return false;
      const bin = m[2]!.split("/").at(-1),
        args = m[3]!;
      return (
        bin === "pnpm" ||
        bin === "vitest" ||
        bin === "ffmpeg" ||
        ((bin === "node" || bin === "tsx") &&
          /(?:^|[/\s])pnpm(?:\.[cm]?js)?(?:\s|$)|vitest|(?:tests|benchmarks|scripts|apps)\//.test(
            args,
          ))
      );
    });
let cache: string | undefined,
  server: Awaited<ReturnType<typeof createServer>> | undefined,
  browser: Awaited<ReturnType<typeof launchRenderBrowser>> | undefined,
  monitor: ReturnType<typeof setInterval> | undefined;
let overlap: string[] = [];
const report: any = {
  status: "in-progress",
  date: new Date().toISOString(),
  profile,
  sourceRef: sourceRef || "working-tree",
  preflightOnly,
  timingValid: null,
  elapsedSessionInvoked: false,
  cases: [],
  method:
    "Five representative family cost diagnostics, paired legacy/WebGL submission/readback with nested inclusive timers and separate synchronization probes. Instrumentation cannot be summed or used as acceptance. Requires an uncontaminated host; preflight-only captures no elapsed metrics.",
};
const retain = () => writeFile(output, JSON.stringify(report, null, 2) + "\n");
try {
  report.diagnosticSha256 = digest(
    await readFile(import.meta.filename, "utf8"),
  );
  const payloadSource = await readFile(
    resolve(
      root,
      "benchmarks/results/composition-ce6p/family-cost-payloads.json",
    ),
    "utf8",
  );
  const prepared = JSON.parse(payloadSource);
  const preparerSource = await readFile(
    resolve(
      root,
      "benchmarks/results/composition-ce6p/prepare-family-costs.mts",
    ),
    "utf8",
  );
  if (digest(preparerSource) !== prepared.preparerSha256)
    throw Error("Preparer source hash mismatch");
  const routes = JSON.parse(
    await readFile(
      resolve(
        root,
        "benchmarks/results/composition-ce6p/failure-route-map.json",
      ),
      "utf8",
    ),
  );
  const expected = new Map(routes.items.map((item: any) => [item.id, item]));
  if (
    prepared.payloads.length !== 5 ||
    new Set(prepared.payloads.map((item: any) => item.id)).size !== 5 ||
    prepared.payloads.some((item: any) => {
      const old: any = expected.get(item.id);
      return (
        !old ||
        old.originalFailure !== item.originalFailure ||
        old.compositionSha256 !== digest(JSON.stringify(item.composition))
      );
    })
  )
    throw Error("Failure coverage/payload mismatch");
  report.inputSha256 = { ...prepared.fixtureSha256 };
  for (const [path, hash] of Object.entries(report.inputSha256))
    if (digest(await readFile(resolve(root, path))) !== hash)
      throw Error("Fixture input hash mismatch: " + path);
  report.assetSha256 = {};
  for (const item of prepared.payloads)
    for (const url of Object.values(item.urls) as string[]) {
      if (!url.startsWith("/@fs/")) throw Error("Unexpected asset URL: " + url);
      const path = url.slice(4);
      report.assetSha256[path] ??= digest(await readFile(path));
    }
  const selection = option("--only", "");
  const cases = prepared.payloads
    .filter((item: any) => !selection || item.id === selection)
    .map((item: any) => item.id);
  if (!cases.length) throw Error("Empty failure selection");
  const paths = execFileSync(
    "git",
    [
      "ls-files",
      "packages/renderer-core/src",
      "packages/scene-contract/src",
      "packages/animation-engine/src",
      "tests/helpers",
    ],
    { cwd: root, encoding: "utf8" },
  )
    .trim()
    .split("\n")
    .filter((p) => p.endsWith(".ts"));
  paths.push(
    "packages/renderer-core/src/composition/render/webgl-disjoint-paints.ts",
    "tests/helpers/composition-effects.ts",
    "tests/helpers/composition-commerce-masks.ts",
    "tests/helpers/paired-render-timing.ts",
  );
  const snapshots = new Map<string, string>();
  report.hostSourceSha256 = {};
  report.sourceSha256 = {};
  for (const path of paths) {
    const actual = await readFile(join(root, path), "utf8");
    report.hostSourceSha256[path] = digest(actual);
    if (sourceRef) {
      if (
        !execFileSync("git", ["ls-tree", "--name-only", sourceRef, path], {
          cwd: root,
          encoding: "utf8",
        }).trim()
      )
        continue;
      snapshots.set(
        join(root, path),
        execFileSync("git", ["show", `${sourceRef}:${path}`], {
          cwd: root,
          encoding: "utf8",
        }),
      );
    } else snapshots.set(join(root, path), actual);
  }
  const helperPath =
    "benchmarks/results/composition-ce6p/family-cost-browser.mjs";
  const helperSource = await readFile(join(root, helperPath), "utf8");
  snapshots.set(join(root, helperPath), helperSource);
  for (const [path, source] of snapshots)
    report.sourceSha256[path.slice(root.length + 1)] = digest(source);
  report.ref = execFileSync("git", ["rev-parse", "HEAD"], {
    cwd: root,
    encoding: "utf8",
  }).trim();
  report.payloadsSha256 = digest(payloadSource);
  report.preparation = {
    preparerSha256: prepared.preparerSha256,
    fixtureSha256: prepared.fixtureSha256,
    dependencies: prepared.preparation,
    coverage: prepared.coverage,
  };
  report.hostCompiler =
    "Precomputed actual working-tree adapter/variant payloads, matched to the prior routing composition hashes. Actual host source hashes and exact supplied composition/URL payload hashes are separate from immutable injected browser sources.";
  report.competingAtStartup = workloads();
  if (!preflightOnly && report.competingAtStartup.length) {
    report.status = "rejected-before-browser-start";
    throw Error("Competing workloads: no elapsed session started");
  }
  monitor = setInterval(() => {
    try {
      overlap = [...new Set([...overlap, ...workloads()])];
    } catch (e) {
      overlap = [...overlap, String(e)];
    }
  }, 2000);
  cache = await mkdtemp(join(tmpdir(), "ce6p-failure-coverage-"));
  server = await createServer({
    root,
    cacheDir: cache,
    configFile: false,
    logLevel: "error",
    plugins: [
      {
        name: "ce6p-immutable-sources",
        enforce: "pre",
        load(id) {
          return snapshots.get(id);
        },
      },
    ],
    server: { host: "127.0.0.1", port: 0 },
  });
  await server.listen();
  browser = await launchRenderBrowser({ profile });
  await retain();
  for (const name of cases) {
    const preparedCase = prepared.payloads.find(
      (item: any) => item.id === name,
    );
    const { composition, legacyScene, urls } = preparedCase;
    const suppliedPayloadSha256 = {
      composition: digest(JSON.stringify(composition)),
      legacyScene: digest(JSON.stringify(legacyScene)),
      urls: digest(JSON.stringify(urls)),
    };
    const page = await browser.newPage();
    await page.addInitScript("window.__name=(fn)=>fn;");
    await page.goto(server.resolvedUrls!.local[0]!);
    const environment = await probeRenderEnvironment(page, profile);
    if (profile === "pinned") assertPinnedRenderEnvironment(environment);
    report.elapsedSessionInvoked = !preflightOnly;
    const result = await page.evaluate(
      async (payload) => {
        const url =
          "/benchmarks/results/composition-ce6p/family-cost-browser.mjs";
        return (await import(url)).measure(payload);
      },
      { composition, legacyScene, urls, preflightOnly },
    );
    report.cases.push({
      name,
      family: preparedCase.family,
      originalFailure: preparedCase.originalFailure,
      recordedRatio: preparedCase.recordedRatio,
      sourcePath: preparedCase.sourcePath,
      sceneSha256: preparedCase.sceneSha256,
      suppliedPayloadSha256,
      environment,
      ...result,
    });
    if (result.error) {
      report.status = "failed-probe-retained";
      await retain();
      throw Error(result.error);
    }
    overlap = [...new Set([...overlap, ...workloads()])];
    report.overlap = overlap;
    report.timingValid = preflightOnly ? null : overlap.length === 0;
    await retain();
    console.log(
      `${name}: retained ${output}; timingValid=${report.timingValid}`,
    );
    if (!preflightOnly && !report.timingValid)
      throw Error("Contaminated measurement retained; stop");
    await page.close();
  }
  for (const [path, hash] of Object.entries(report.inputSha256))
    if (digest(await readFile(resolve(root, path))) !== hash)
      throw Error("Fixture changed during trace: " + path);
  for (const [path, hash] of Object.entries(report.assetSha256))
    if (digest(await readFile(path)) !== hash)
      throw Error("Asset changed during trace: " + path);
  for (const [path, sha] of Object.entries(report.hostSourceSha256))
    if (digest(await readFile(resolve(root, path))) !== sha)
      throw Error("Host source changed during diagnostic: " + path);
  report.inputsAndAssetsUnchanged = true;
  report.coverage = {
    selected: cases.length,
    traced: report.cases.length,
    originalFailures: report.cases.filter((item: any) => item.originalFailure)
      .length,
  };
  report.status = "complete";
  await retain();
} catch (error) {
  if (report.status !== "rejected-before-browser-start")
    report.status = "failed";
  report.error = String(error);
  report.overlap = overlap;
  report.timingValid = preflightOnly ? null : false;
  await retain();
  throw error;
} finally {
  if (monitor) clearInterval(monitor);
  const closed = await Promise.allSettled([browser?.close(), server?.close()]);
  if (cache)
    closed.push(
      ...(await Promise.allSettled([
        rm(cache, { recursive: true, force: true }),
      ])),
    );
  const failed = closed.filter((result) => result.status === "rejected");
  if (failed.length) {
    report.status = "cleanup-failed";
    report.cleanupErrors = failed.map((result) =>
      String((result as PromiseRejectedResult).reason),
    );
    await retain();
    process.exitCode = 1;
  }
}

