import {
  createCompositionPreview,
  loadCompositionResources,
  createIllustratedPreview,
  loadIllustratedImages,
} from "../../../packages/renderer-core/src/index.ts";
import { WebglDevice } from "../../../packages/renderer-core/src/composition/render/webgl-device.ts";
import { WebglPaint } from "../../../packages/renderer-core/src/composition/render/webgl-paint.ts";
import { WebglVectors } from "../../../packages/renderer-core/src/composition/render/webgl-vectors.ts";
import { WebglReadback } from "../../../packages/renderer-core/src/composition/render/webgl-readback.ts";

export async function measure({
  composition,
  legacyScene,
  urls,
  preflightOnly,
}) {
  let legacy,
    preview,
    enabled = false,
    stats = {},
    result,
    currentProbe,
    byteFailure,
    timedProbeStarted = false;
  const completedRuns = [];
  const restores = [],
    oldCanvas = document.createElement("canvas"),
    canvas = document.createElement("canvas");
  const digest = async (bytes) =>
    Array.from(
      new Uint8Array(await crypto.subtle.digest("SHA-256", bytes)),
      (v) => v.toString(16).padStart(2, "0"),
    ).join("");
  const hook = (target, name) => {
    const original = target[name];
    target[name] = function (...args) {
      if (!enabled) return Reflect.apply(original, this, args);
      const at = performance.now();
      let key = target.constructor.name + "." + name;
      if (name === "copyRegion" && this.solidColor(args[0], args[1]))
        key += "/knownClear";
      try {
        return Reflect.apply(original, this, args);
      } finally {
        const value = (stats[key] ??= { calls: 0, ms: 0 });
        value.calls++;
        if (name.startsWith("upload")) {
          const surface = args[0],
            rect = name === "uploadArea" ? args[2] : null;
          const area = rect
            ? (rect.right - rect.left) * (rect.bottom - rect.top)
            : name === "upload"
              ? args[1].width * args[1].height
              : surface.width * surface.height;
          value.submittedUploadBytes =
            (value.submittedUploadBytes ?? 0) +
            area * (name === "uploadFloats" ? 16 : 4);
        }
        if (name === "copyRegion") {
          const rect = args[1];
          value.submittedCopiedPixels =
            (value.submittedCopiedPixels ?? 0) +
            (rect.right - rect.left) * (rect.bottom - rect.top);
        }
        value.ms += performance.now() - at;
      }
    };
    restores.push(() => (target[name] = original));
  };
  try {
    const resources = await loadCompositionResources(
      composition,
      (id) => urls[id],
    );
    legacy = createIllustratedPreview(
      oldCanvas,
      legacyScene,
      await loadIllustratedImages(legacyScene, (id) => urls[id]),
    );
    preview = createCompositionPreview(canvas, composition, resources, {
      backend: "webgl2",
    });
    const gl = canvas.getContext("webgl2"),
      ctx = oldCanvas.getContext("2d");
    const readLegacy = () =>
      ctx.getImageData(0, 0, composition.width, composition.height).data;
    const selected = [
      ...new Set([0, 24, 96, composition.frameCount - 1]),
    ].filter((f) => f < composition.frameCount);
    const frame = (backend, n) => {
      const p = backend === "webgl2" ? preview : legacy;
      p.renderFrame(n);
      return backend === "webgl2" ? preview.readPixels() : readLegacy();
    };
    if (preflightOnly) {
      const frames = [];
      for (const n of selected)
        frames.push({
          frame: n,
          legacySha256: await digest(frame("legacy", n)),
          webglSha256: await digest(frame("webgl2", n)),
        });
      return (result = {
        rendererVersion: preview.rendererVersion,
        frames,
        elapsedTimingsCaptured: false,
      });
    }
    // Match the existing paired timing helper's complete untimed warm traversal.
    for (let n = 0; n < composition.frameCount; n++) {
      frame("legacy", n);
      frame("webgl2", n);
    }
    for (const name of [
      "upload",
      "uploadRegion",
      "uploadArea",
      "uploadBytes",
      "uploadFloats",
      "copyRegion",
      "pass",
      "readRegion",
    ])
      hook(WebglDevice.prototype, name);
    for (const name of ["draw", "drawMany"]) hook(WebglPaint.prototype, name);
    for (const name of ["paint", "drawBatch"])
      hook(WebglVectors.prototype, name);
    hook(WebglReadback.prototype, "read");
    hook(Uint8ClampedArray.prototype, "slice");
    const runs = completedRuns,
      baselineHashes = new Map();
    for (let cycle = 0; cycle < 6; cycle++) {
      const modes = [
        ["legacy", false, false],
        ["webgl2", false, false],
        ["webgl2", true, false],
        ["webgl2", true, true],
      ];
      if (cycle % 2) modes.reverse();
      for (const [backend, instrumented, barrier] of modes) {
        const frames = [];
        stats = {};
        currentProbe = { cycle, backend, instrumented, barrier, frames, stats };
        for (const n of selected) {
          enabled = false;
          frame(
            backend,
            n === 0 ? composition.frameCount - 1 : Math.max(0, n - 3),
          );
          for (let warm = Math.max(0, n - 2); warm < n; warm++)
            frame(backend, warm);
          enabled = instrumented;
          timedProbeStarted = true;
          const at = performance.now();
          (backend === "webgl2" ? preview : legacy).renderFrame(n);
          const submitted = performance.now();
          if (barrier) {
            gl.bindFramebuffer(gl.FRAMEBUFFER, null);
            gl.readPixels(
              0,
              0,
              1,
              1,
              gl.RGBA,
              gl.UNSIGNED_BYTE,
              new Uint8Array(4),
            );
          }
          const completed = performance.now(),
            pixels = backend === "webgl2" ? preview.readPixels() : readLegacy(),
            end = performance.now();
          enabled = false;
          if (pixels.length !== composition.width * composition.height * 4)
            throw Error("Owned byte length");
          const pixelsSha256 = await digest(pixels),
            key = backend + ":" + n;
          frames.push({
            frame: n,
            renderMs: submitted - at,
            barrierMs: completed - submitted,
            readMs: end - completed,
            totalMs: end - at,
            pixelsSha256,
          });
          if (
            baselineHashes.has(key) &&
            baselineHashes.get(key) !== pixelsSha256
          ) {
            byteFailure = {
              cycle,
              backend,
              instrumented,
              barrier,
              frame: n,
              expectedSha256: baselineHashes.get(key),
              actualSha256: pixelsSha256,
            };
            throw Error("Byte stability failed: " + key);
          }
          baselineHashes.set(key, pixelsSha256);
        }
        runs.push({
          cycle,
          backend,
          instrumented,
          barrier,
          frames,
          stats: structuredClone(stats),
        });
      }
    }
    return (result = {
      rendererVersion: preview.rendererVersion,
      size: [composition.width, composition.height],
      runs,
      elapsedTimingsCaptured: true,
      acceptance: false,
      method:
        "Four prescribed frames per workload, six alternating orders. Each selected frame has separate untimed reset/warmup. Inclusive nested costs cannot be summed; readback can absorb queued work. One-pixel barrier includes its own probe cost. Pixel hashes agree per backend across instrumented/uninstrumented probes. Representative costs do not establish whole-family timing closure. A complete paired forward traversal precedes timers to match the existing warmup protocol; browser adaptive Canvas behavior is not forced or disabled.",
    });
  } catch (error) {
    return (result = {
      status: "failed-probe",
      partialProbe: currentProbe,
      byteFailure,
      error: String(error),
      rendererVersion: preview?.rendererVersion,
      runs: completedRuns,
      elapsedTimingsCaptured: timedProbeStarted,
      acceptance: false,
    });
  } finally {
    enabled = false;
    const cleanupErrors = [];
    for (const restore of restores.reverse())
      try {
        restore();
      } catch (e) {
        cleanupErrors.push(String(e));
      }
    for (const p of [preview, legacy])
      try {
        p?.dispose();
      } catch (e) {
        cleanupErrors.push(String(e));
      }
    if (cleanupErrors.length) {
      result.status = "failed-cleanup";
      result.error ??= "Probe cleanup failed";
      result.cleanupErrors = cleanupErrors;
    }
  }
}

