import { createCompositionPreview } from "../../../packages/renderer-core/src/index.ts";
import { WebglPaint } from "../../../packages/renderer-core/src/composition/render/webgl-paint.ts";
import { WebglReadback } from "../../../packages/renderer-core/src/composition/render/webgl-readback.ts";
const composition = {
  schemaVersion: "composition-1",
  id: "exposure-cost",
  width: 1920,
  height: 1080,
  fps: 30,
  frameCount: 60,
  background: "#26313b",
  assets: [],
  motionBlur: {
    enabled: false,
    shutterAngle: 360,
    shutterPhase: 0,
    samples: 2,
  },
  layers: [
    {
      id: "moving",
      type: "solid",
      size: [400, 300],
      color: "#d87047",
      motionBlur: true,
      transform: {
        anchor: [0, 0],
        position: {
          x: {
            keys: [
              { frame: 0, value: 100 },
              { frame: 59, value: 1400, interpolation: "linear" },
            ],
          },
          y: 300,
        },
        opacity: 0.6,
      },
    },
  ],
};

const PAINT_CLEAR = `uniform vec2 origin; uniform vec4 region; uniform vec4 backdropColor; uniform float primitive;
void main() {
  vec2 p=gl_FragCoord.xy;
  vec4 s=vec4(0.0);
  if(p.x>=region.x && p.y>=region.y && p.x<region.z && p.y<region.w)
    s=floor(texelFetch(source,ivec2(p-origin),0)*255.0+0.5);
  vec4 d=backdropColor;
  pixel=(primitive > 0.5 ? s+floor(d*(256.0-s.a)/256.0) : floor(s+d*(1.0-s.a/255.0)+0.5))/255.0;
}`;
export async function measure({preflightOnly}) {
  const previews = {}, restores = [], byteChecks = [], baselineByteChecks = [], runs = [], expectedHashes = new Map(), canvasHashes = new Map(), variants = ["baseline", "paint-only", "owned-only", "both"];
  let variant = "baseline", result, byteFailure, currentTraversal, timedProbeStarted = false, optimizedPaints = 0, freshReads = 0;
  const digest = async bytes => Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",bytes)), v => v.toString(16).padStart(2,"0")).join("");
