  } catch(e) { result ??= {composition,byteChecks,baselineByteChecks,runs,acceptance:false}; result.byteFailure=byteFailure; result.canvasReferenceHashes=Object.fromEntries(canvasHashes); result.error=String(e); result.elapsedTimingsCaptured=timedProbeStarted; result.partialTraversal=currentTraversal; result.optimizedPaints=optimizedPaints; result.freshReads=freshReads; }
  finally {
    const cleanup=[];
    for(const restore of restores.reverse()) try {restore();}catch(e){cleanup.push(String(e));}
    for(const p of Object.values(previews)) try {p.dispose();}catch(e){cleanup.push(String(e));}
    if(cleanup.length){result ??={}; result.error ??="Probe cleanup failed";result.cleanupErrors=cleanup;}
  }
  return result;
}

