from pathlib import Path
from datetime import datetime, timezone
import hashlib,json,subprocess,time,sys,signal
root=Path('/Users/jjae/.codex/worktrees/6cea/still-shift')
base=root/'benchmarks/results/composition-ce6p'
report_path=base/'native-owned-dispatch-repaired.json'
node='/Users/jjae/.nvm/versions/node/v22.23.1/bin/node'
files=['native-owned-dispatch.py','native-owned-gate.mts','native-owned-gate-browser.mjs']
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
now=lambda:datetime.now(timezone.utc).isoformat()
report={'status':'waiting-for-three-continuous-quiet-minutes','date':now(),'observations':[],'sessions':[],'sourceSha256':{name:sha(base/name) for name in files},'method':'Observe existing verification finishing without process control. Same competing verification predicate as native diagnostic. Three continuous quiet minutes required; then two serial profile diagnostics, each with its own startup/whole-session guard. No acceptance claim.'}
def retain(): report_path.write_text(json.dumps(report,indent=2)+'\n')
def workloads():
    rows=[]
    for line in subprocess.check_output(['ps','-axo','pid,command'],text=True).splitlines()[1:]:
        fields=line.split(None,2)
        if len(fields)<2: continue
        pid=int(fields[0]);exe=fields[1].split('/')[-1];args=fields[2] if len(fields)>2 else ''
        if exe in ['pnpm','vitest','ffmpeg'] or exe in ['node','tsx'] and any(x in args for x in ['pnpm','vitest','tests/','benchmarks/','scripts/','apps/']): rows.append({'pid':pid,'command':fields[1]+' '+args})
    return rows
retain()
try:
    quiet_since=None
    last_count=None
    while True:
        busy=workloads();at=time.monotonic()
        if busy: quiet_since=None
        elif quiet_since is None: quiet_since=at
        seconds=0 if quiet_since is None else at-quiet_since
        report['observations'].append({'date':now(),'competing':busy,'continuousQuietSeconds':seconds});retain()
        if len(busy)!=last_count:
            print('OBSERVE',now(),'competing',len(busy),flush=True);last_count=len(busy)
        if seconds>=180:break
        time.sleep(5)
    report['status']='running';report['quietReadyAt']=now();retain()
    print('QUIET_READY',now(),flush=True)
    for profile in ['pinned','hardware']:
        for name,expected in report['sourceSha256'].items():
            if sha(base/name)!=expected:raise RuntimeError('Dispatch source changed: '+name)
        output=base/f'native-owned-gate-repaired-{profile}.json';log=base/f'native-owned-gate-repaired-{profile}.log'
        args=[node,'--import','tsx','benchmarks/results/composition-ce6p/native-owned-gate.mts','--output',str(output)]
        if profile=='hardware':args.append('--hardware')
        session={'profile':profile,'start':now(),'status':'running','output':str(output.relative_to(root)),'log':str(log.relative_to(root))};report['sessions'].append(session);retain()
        print('START',profile,now(),flush=True)
        with log.open('w') as stream:
            child=subprocess.Popen(args,cwd=root,stdout=stream,stderr=subprocess.STDOUT,start_new_session=True)
            try:
                session['ownedChildPid']=child.pid;retain()
                exit_code=child.wait()
            except BaseException as child_error:
                session['cleanupRequests']=[]
                if child.poll() is None:
                    session['cleanupRequests'].append('SIGINT to owned diagnostic child');child.send_signal(signal.SIGINT)
                    try:child.wait(timeout=30)
                    except subprocess.TimeoutExpired:
                        session['cleanupRequests'].append('SIGTERM to owned diagnostic child');child.terminate()
                        try:child.wait(timeout=10)
                        except subprocess.TimeoutExpired:
                            session['cleanupRequests'].append('SIGKILL to owned diagnostic child');child.kill();child.wait()
                stream.flush()
                session.update(exitCode=child.returncode,end=now(),status='interrupted',error=repr(child_error),logSha256=sha(log))
                if output.exists():session['rawSha256']=sha(output)
                retain()
                raise
        session.update(exitCode=exit_code,end=now(),status='complete' if exit_code==0 else 'failed',logSha256=sha(log))
        if output.exists():session['rawSha256']=sha(output)
        retain();print('END',profile,exit_code,now(),flush=True)
        if exit_code:raise RuntimeError('Diagnostic failed; later profiles not run')
    report['status']='complete';retain()
except BaseException as error:
    report['status']='failed';report['error']=repr(error);retain();raise

