  const stationary={id:"stationary",type:"solid",size:[70,40],color:"#238cae",transform:{anchor:[0,0],position:{x:160,y:125},opacity:0.37}};
  const opaque={...structuredClone(moving),id:"opaque",size:[320,170],transform:{anchor:[0,0],position:{x:0,y:0},opacity:1}};
  const fixtures=[
    make("moving-with-static-disjoint",{layers:[moving,stationary]}),
    make("moving-with-static-overlap",{layers:[moving,{...stationary,transform:{anchor:[0,0],position:{x:100,y:30},opacity:0.37}}]}),
    make("reverse-order",{layers:[{...stationary,transform:{anchor:[0,0],position:{x:100,y:30},opacity:0.37}},moving]}),
    make("offscreen",{layers:[{...structuredClone(moving),transform:{anchor:[0,0],position:{x:{keys:[{frame:0,value:-70},{frame:11,value:350,interpolation:"linear"}]},y:30},opacity:0.6}},stationary]}),
    make("fractional-y",{layers:[{...structuredClone(moving),transform:{anchor:[0,0],position:{x:20.31,y:30.61},opacity:{keys:[{frame:0,value:0},{frame:11,value:1,interpolation:"linear"}]}}},stationary]}),
    make("rotation",{layers:[{...structuredClone(moving),transform:{anchor:[0,0],position:{x:140,y:50},rotation:{keys:[{frame:0,value:-10},{frame:11,value:60,interpolation:"linear"}]},opacity:0.6}},stationary]}),
    make("dense-fallback",{layers:[opaque,moving]}),
    make("empty",{layers:[]}),
    make("fractional-clear",{background:"#26313b6e",layers:[moving,stationary]}),
    make("empty-fractional-clear",{background:"#26313b6e",layers:[]}),
    make("exposure",{motionBlur:{enabled:true,shutterAngle:180,shutterPhase:0,samples:4},layers:[{...structuredClone(moving),motionBlur:true},stationary]}),
  ];
  const results=[];
  for(const fixture of fixtures) { const result=await nativeProof(fixture); results.push({name:fixture.id,...result});  }
  return {results,error:results.some(r=>r.error)?"One or more control fixtures failed":undefined,elapsedTimingsCaptured:false,acceptance:false};
}

