import { createCompositionPreview, loadCompositionResources } from "../../../packages/renderer-core/src/index.ts";
import { WebglImages } from "../../../packages/renderer-core/src/composition/render/webgl-images.ts";
import { WebglVectors } from "../../../packages/renderer-core/src/composition/render/webgl-vectors.ts";

export async function measure({ composition, urls }) {
  const restores = [], previews = [], summaries = new Map(), instances = new WeakMap();
  let active = false, phase = "forward", frame = -1, visit = 0, result;
  const completedFrames = [];
  const digest = async (data) => Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256", data)), v => v.toString(16).padStart(2,"0")).join("");
  const record = (owner, kind, id, key, entry, layer) => {
    let owners = instances.get(owner);
    if (!owners) instances.set(owner, owners = new Map());
    let seen = owners.get(id);
    if (!seen) owners.set(id, seen = new Map());
    const bucket = `${phase}/${kind}/${layer}`;
    let summary = summaries.get(bucket);
    if (!summary) summaries.set(bucket, summary = { phase, kind, layer, calls: 0, hits: 0, newKeyMisses: 0, repeatedKeyMisses: 0, sameFrameRepeatedMisses: 0, previouslyRetainedKeyMisses: 0, previouslyUnretainedAttemptMisses: 0, successfulRetentions: 0, retainedBytesAtMiss: 0, repeatedKeyMissExamples: [] });
    summary.calls++;
    const previous = seen.get(key), oldFrame = previous?.lastAttemptFrame;
    if (entry?.key === key) summary.hits++;
    else if (seen.has(key)) {
      summary.repeatedKeyMisses++;
      if (previous?.everRetained) { summary.previouslyRetainedKeyMisses++; if (previous.lastVisit === visit) summary.sameFrameRepeatedMisses++; } else summary.previouslyUnretainedAttemptMisses++;
      summary.retainedBytesAtMiss += owner.bytes;
      if (summary.repeatedKeyMissExamples.length < 4) summary.repeatedKeyMissExamples.push({ frame, priorFrame: oldFrame, previousKeyPresent: !!entry, previouslyRetained: previous?.everRetained === true });
    } else summary.newKeyMisses++;
    const next = { lastAttemptFrame: frame, lastVisit: visit, everRetained: previous?.everRetained === true };
    seen.set(key, next);
    return retained => { if (retained) { next.everRetained = true; summary.successfulRetentions++; } };
  };
  try {
    const resources = await loadCompositionResources(composition, id => urls[id]);
    for (let i=0;i<2;i++) previews.push(createCompositionPreview(document.createElement("canvas"), composition, resources, { backend: "webgl2" }));
    if (previews.some(p => p.rendererVersion !== "composition-webgl2-0.42.0")) throw Error("Unexpected runtime version");
    const images = WebglImages.prototype.draw;
    WebglImages.prototype.draw = function(dst, content, matrix, opacity, clips, transforms) {
      let finish, key;
      if (active) {
        key = JSON.stringify([content, matrix, opacity, clips, transforms, dst.width, dst.height]);
        finish = record(this, "image", content.sources, key, this.cached.get(content.sources), content.sources.map(s => s.asset).join(","));
      }
      try { return Reflect.apply(images, this, arguments); } finally { finish?.(this.cached.get(content.sources)?.key === key); }
    };
    restores.push(() => WebglImages.prototype.draw = images);
    const vectors = WebglVectors.prototype.drawBatch;
    WebglVectors.prototype.drawBatch = function(dst, ops, region) {
      let finish, key, id;
      if (active) {
        id = JSON.stringify([dst.width, dst.height, ops.map(op => op.layer)]);
        key = this.keys.of([ops, this.paintOver.hasBackdrop(dst)]);
        finish = record(this, "vector", id, key, this.cached.get(id), ops.map(op => op.layer).join(","));
      }
      try { return Reflect.apply(vectors, this, arguments); } finally { finish?.(this.cached.get(id)?.key === key); }
    };
    restores.push(() => WebglVectors.prototype.drawBatch = vectors);
    for (phase of ["forward", "reverse"]) {
      const frames = Array.from({length: composition.frameCount}, (_,i) => phase === "forward" ? i : composition.frameCount-i-1);
      for (frame of frames) {
        visit++;
        active = false;
        previews[0].renderFrame(frame);
        const expected = previews[0].readPixels();
        active = true;
        previews[1].renderFrame(frame);
        const actual = previews[1].readPixels();
        active = false;
        const expectedSha256 = await digest(expected), actualSha256 = await digest(actual);
        completedFrames.push({phase, frame, expectedSha256, actualSha256});
        if (expectedSha256 !== actualSha256) throw Error(`Trace byte difference ${phase}/${frame}`);
      }
    }
    result = { rendererVersion: previews[1].rendererVersion, summaries: [...summaries.values()], frames: completedFrames, elapsedTimingsCaptured: false, acceptance: false };
  } catch (error) {
    result = {error: String(error), summaries: [...summaries.values()], frames: completedFrames, elapsedTimingsCaptured: false, acceptance: false};
  } finally {
    active = false;
    const errors = [];
    for (const restore of restores.reverse()) try {restore();} catch(e) {errors.push(String(e));}
    for (const preview of previews) try {preview.dispose();} catch(e) {errors.push(String(e));}
    if (errors.length) { result ??= {}; result.error ??= "Trace cleanup failed"; result.cleanupErrors = errors; }
  }
  return result;
}

