import { createCompositionPreview } from "../../../packages/renderer-core/src/index.ts";
import { WebglPaint } from "../../../packages/renderer-core/src/composition/render/webgl-paint.ts";
import { WebglReadback } from "../../../packages/renderer-core/src/composition/render/webgl-readback.ts";
const composition = {
  schemaVersion: "composition-1",
  id: "exposure-cost",
  width: 1920,
  height: 1080,
  fps: 30,
  frameCount: 60,
  background: "#26313b",
  assets: [],
  motionBlur: {
    enabled: false,
    shutterAngle: 360,
    shutterPhase: 0,
    samples: 2,
  },
  layers: [
    {
      id: "moving",
      type: "solid",
      size: [400, 300],
      color: "#d87047",
      motionBlur: true,
      transform: {
        anchor: [0, 0],
        position: {
          x: {
            keys: [
              { frame: 0, value: 100 },
              { frame: 59, value: 1400, interpolation: "linear" },
            ],
          },
          y: 300,
        },
        opacity: 0.6,
      },
    },
  ],
};

const PAINT_CLEAR = `uniform vec2 origin; uniform vec4 region; uniform vec4 backdropColor; uniform float primitive;
void main() {
  vec2 p=gl_FragCoord.xy;
  vec4 s=vec4(0.0);
  if(p.x>=region.x && p.y>=region.y && p.x<region.z && p.y<region.w)
    s=floor(texelFetch(source,ivec2(p-origin),0)*255.0+0.5);
  vec4 d=backdropColor;
  pixel=(primitive > 0.5 ? s+floor(d*(256.0-s.a)/256.0) : floor(s+d*(1.0-s.a/255.0)+0.5))/255.0;
}`;
export async function measure({preflightOnly}) {
  const previews = {}, restores = [], byteChecks = [], baselineByteChecks = [], runs = [], expectedHashes = new Map(), variants = ["baseline", "paint-only", "owned-only", "both"];
  let variant = "baseline", result, byteFailure, currentTraversal, timedProbeStarted = false, optimizedPaints = 0, freshReads = 0;
  const digest = async bytes => Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",bytes)), v => v.toString(16).padStart(2,"0")).join("");
  const render = (name, frame) => { variant = name; const p=previews[name]; p.renderFrame(frame); return p.readPixels(); };
  try {
    for (const name of [...variants,"canvas2d"]) previews[name] = createCompositionPreview(document.createElement("canvas"), composition, {images:new Map(), fonts:new Map()}, {backend:name === "canvas2d" ? name : "webgl2"});
    if (variants.some(name => previews[name].rendererVersion !== "composition-webgl2-0.42.0")) throw Error("Unexpected underlying version");
    const paint = WebglPaint.prototype.draw;
    WebglPaint.prototype.draw = function(source, dst, rect, primitive = true, bitmapRounding = false) {
      if ((variant === "paint-only" || variant === "both") && dst.screen && !dst.floating && (primitive || bitmapRounding)) {
        const active = this.device.drawRegion(dst, rect), color = active && this.device.solidColor(dst, active);
        if (color) {
          this.device.pass(PAINT_CLEAR, dst, [source], {origin:[rect.left,rect.top], region:[rect.left,rect.top,rect.right,rect.bottom], backdropColor:color, primitive:primitive && !bitmapRounding ? 1 : 0}, false, active);
          this.bounds.include(dst,rect);
          optimizedPaints++;
          return;
        }
      }
      return Reflect.apply(paint,this,arguments);
    };
    restores.push(() => WebglPaint.prototype.draw = paint);
    const read = WebglReadback.prototype.read;
    WebglReadback.prototype.read = function() {
      if (variant === "owned-only" || variant === "both") { freshReads++; return this.readFull(); }
      return Reflect.apply(read,this,arguments);
    };
    restores.push(() => WebglReadback.prototype.read = read);
    // Fixed complete traversals and repeated/random seeks for the native fixture.
    const frames = [...Array.from({length:60},(_,i)=>i), ...Array.from({length:60},(_,i)=>59-i), 24,24,0,59,17,3,44,20,28];
    for (const frame of frames) {
      const expected = render("baseline", frame), expectedSha256 = await digest(expected);
      baselineByteChecks.push({frame,pixelsSha256:expectedSha256});
      if(expectedHashes.has(frame) && expectedHashes.get(frame)!==expectedSha256) { byteFailure={variant:"baseline",frame,expectedSha256:expectedHashes.get(frame),actualSha256:expectedSha256}; throw Error(`Baseline determinism failure ${frame}`); }
      if(!expectedHashes.has(frame)) expectedHashes.set(frame,expectedSha256);
      for (const name of variants.slice(1)) {
        const actual = render(name,frame), actualSha256 = await digest(actual);
        byteChecks.push({variant:name,frame,expectedSha256,actualSha256});
        if (actual.length !== 8294400 || actualSha256 !== expectedSha256) { byteFailure={variant:name,frame,expectedSha256,actualSha256}; throw Error(`Byte failure ${name}/${frame}`); }
        const pristine = actual[0]; actual[0] ^= 255;
        variant=name; const reread = previews[name].readPixels();
        if (reread === actual || reread.buffer === actual.buffer || reread[0] !== pristine || await digest(reread) !== expectedSha256) throw Error(`Ownership failure ${name}/${frame}`);
      }
    }
    if (!optimizedPaints || !freshReads) throw Error("Mechanism not exercised");
    result = {composition, underlyingRendererVersion:previews.baseline.rendererVersion, proposalRuntimeVersion:"diagnostic-overlay-on-0.42.0", byteChecks, baselineByteChecks, preflightOptimizedPaints:optimizedPaints, preflightFreshReads:freshReads, elapsedTimingsCaptured:false, acceptance:false, correctnessScope:"Fixed native moving-solid fixture only; general fallback/eligibility/changed-background controls and fresh-to-cached transition obligations remain pending before any production retention. Every preview stays in its assigned mode.", runs};
    if (!preflightOnly) {
      optimizedPaints=0;freshReads=0;
      const order=["canvas2d",...variants];
      for (let cycle=0;cycle<8;cycle++) {
        for (const name of cycle%2 ? [...order].reverse() : order) {
          const p=previews[name];render(name,20);
          const samples=[];
          currentTraversal={cycle,variant:name,frames:samples};
          for (let frame=21;frame<29;frame++) {
            variant=name;
            timedProbeStarted=true;
            const at=performance.now();p.renderFrame(frame);const rendered=performance.now();const pixels=p.readPixels();const completed=performance.now();
            if(pixels.length!==8294400) throw Error("Owned byte length");
            if(frame>=24) { const pixelsSha256=await digest(pixels); samples.push({frame,renderMs:rendered-at,readMs:completed-rendered,totalMs:completed-at,pixelsSha256}); if(pixelsSha256!==expectedHashes.get(frame)) throw Error(`Timed byte failure ${name}/${frame}`); }
          }
          runs.push(currentTraversal);currentTraversal=undefined;
        }
      }
      result.elapsedTimingsCaptured=true;
      result.timedOptimizedPaints=optimizedPaints;result.timedFreshReads=freshReads;
    }
    result.method="Diagnostic gate only, original native CE7 count-one fixture and frame window: frame20 setup/warmup,21–23 warm,24–28 measured, eight alternating variant orders with Canvas controls. Three scoped mechanism ablations remain isolated monkey-patch overlays; no production source changes, flags, policy, or acceptance changes. Fresh read on this fixed exact-clear fixture uses existing bounded WebglBounds.read; general fallback correctness is unproven and no production eligibility is proposed; no buffer reuse or asynchronous output. Full deterministic byte/ownership preflight precedes timing; its allocations may affect later GC and timings are environmental observations.";
  } catch(e) { result ??= {composition,byteChecks,baselineByteChecks,runs,acceptance:false}; result.byteFailure=byteFailure; result.error=String(e); result.elapsedTimingsCaptured=timedProbeStarted; result.partialTraversal=currentTraversal; result.optimizedPaints=optimizedPaints; result.freshReads=freshReads; }
  finally {
    const cleanup=[];
    for(const restore of restores.reverse()) try {restore();}catch(e){cleanup.push(String(e));}
    for(const p of Object.values(previews)) try {p.dispose();}catch(e){cleanup.push(String(e));}
    if(cleanup.length){result ??={}; result.error ??="Probe cleanup failed";result.cleanupErrors=cleanup;}
  }
  return result;
}
